/**
 * AI RENDER LOOKS: a small, editable description of how the 3D model should look in a render —
 * sky, haze, exposure, sun direction / colour, ambient light, ground and a material per element
 * category. It is applied live to the three.js scene (no geometry rebuild, elements stay linked to
 * the model), so a look can be generated by AI from a brief, tweaked with sliders, and re-used.
 */
import type { EntityType } from '../types/model';

export type LookCategory =
  | 'walls'
  | 'floors'
  | 'roof'
  | 'doors'
  | 'windows'
  | 'stairs'
  | 'structure'
  | 'furniture'
  | 'railings'
  | 'other';

export const LOOK_CATEGORIES: { id: LookCategory; label: string }[] = [
  { id: 'walls', label: 'Walls' },
  { id: 'floors', label: 'Floors & slabs' },
  { id: 'roof', label: 'Roof' },
  { id: 'doors', label: 'Doors' },
  { id: 'windows', label: 'Window frames' },
  { id: 'stairs', label: 'Stairs' },
  { id: 'structure', label: 'Structure' },
  { id: 'furniture', label: 'Furniture & blocks' },
  { id: 'railings', label: 'Railings' },
  { id: 'other', label: 'Other' },
];

export interface LookMaterial {
  /** #rrggbb; omitted = keep the model's own colour */
  color?: string;
  roughness?: number; // 0–1
  metalness?: number; // 0–1
}

export interface RenderLook {
  name: string;
  /** sky gradient, zenith → horizon */
  skyTop: string;
  skyBottom: string;
  /** atmospheric haze colour + density 0–1 (0 = none) */
  fogColor: string;
  fogDensity: number;
  /** tone-mapping exposure, 0.3–2.5 */
  exposure: number;
  /** compass degrees (0 = north / +y of the plan, 90 = east) and altitude 0–90° */
  sunAzimuth: number;
  sunAltitude: number;
  sunColor: string;
  sunIntensity: number; // 0–5
  ambientSky: string;
  ambientGround: string;
  ambientIntensity: number; // 0–3
  groundColor: string;
  /** dark outline edges on/off */
  edges: boolean;
  materials: Partial<Record<LookCategory, LookMaterial>>;
  /** the art-direction text a photoreal pass should follow */
  photoPrompt?: string;
}

/** Which look category a model entity belongs to (null = not restyled, e.g. 2D drafting). */
export function lookCategoryOf(type: EntityType | string, key = ''): LookCategory | null {
  if (key.startsWith('hub:')) return 'walls';
  switch (type) {
    case 'wall':
    case 'sweep':
      return 'walls';
    case 'floor':
    case 'room':
    case 'balcony':
    case 'footing':
      return 'floors';
    case 'roof':
    case 'dormer':
    case 'skylight':
      return 'roof';
    case 'door':
      return 'doors';
    case 'window':
    case 'wallopening':
      return 'windows';
    case 'stair':
      return 'stairs';
    case 'column':
    case 'beam':
    case 'beamsystem':
    case 'truss':
    case 'connection':
      return 'structure';
    case 'block':
    case 'object':
    case 'custom':
      return 'furniture';
    case 'railing':
      return 'railings';
    case 'camera':
    case 'grid':
    case 'dimension':
    case 'text':
    case 'leader':
    case 'tag':
    case 'section':
    case 'hatch':
    case 'load':
    case 'rebar':
    case 'areareinf':
      return null;
    default:
      return 'other';
  }
}

const HEX = /^#[0-9a-f]{6}$/i;
const clamp = (v: unknown, lo: number, hi: number, d: number) => {
  const n = typeof v === 'number' ? v : Number(v);
  return Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : d;
};
const hex = (v: unknown, d: string) => {
  if (typeof v !== 'string') return d;
  let s = v.trim();
  if (/^#?[0-9a-f]{3}$/i.test(s)) s = '#' + s.replace('#', '').split('').map((c) => c + c).join('');
  if (!s.startsWith('#')) s = '#' + s;
  return HEX.test(s) ? s.toLowerCase() : d;
};

