/** Normalize anything (AI output, saved JSON) into a valid look; missing parts fall back to `base`. */
export function normalizeLook(raw: unknown, base: RenderLook = DEFAULT_LOOK): RenderLook {
  const r = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
  const mats: RenderLook['materials'] = {};
  const rm = (r.materials && typeof r.materials === 'object' ? r.materials : {}) as Record<string, unknown>;
  for (const { id } of LOOK_CATEGORIES) {
    const src = rm[id] as Record<string, unknown> | undefined;
    const b = base.materials[id];
    if (!src || typeof src !== 'object') {
      if (b) mats[id] = { ...b };
      continue;
    }
    const m: LookMaterial = {};
    const c = hex(src.color, b?.color ?? '');
    if (c) m.color = c;
    m.roughness = clamp(src.roughness, 0, 1, b?.roughness ?? 0.7);
    m.metalness = clamp(src.metalness, 0, 1, b?.metalness ?? 0);
    mats[id] = m;
  }
  return {
    name: typeof r.name === 'string' && r.name.trim() ? r.name.trim().slice(0, 40) : base.name,
    skyTop: hex(r.skyTop, base.skyTop),
    skyBottom: hex(r.skyBottom, base.skyBottom),
    fogColor: hex(r.fogColor, base.fogColor),
    fogDensity: clamp(r.fogDensity, 0, 1, base.fogDensity),
    exposure: clamp(r.exposure, 0.3, 2.5, base.exposure),
    sunAzimuth: ((clamp(r.sunAzimuth, -720, 720, base.sunAzimuth) % 360) + 360) % 360,
    sunAltitude: clamp(r.sunAltitude, 0, 90, base.sunAltitude),
    sunColor: hex(r.sunColor, base.sunColor),
    sunIntensity: clamp(r.sunIntensity, 0, 5, base.sunIntensity),
    ambientSky: hex(r.ambientSky, base.ambientSky),
    ambientGround: hex(r.ambientGround, base.ambientGround),
    ambientIntensity: clamp(r.ambientIntensity, 0, 3, base.ambientIntensity),
    groundColor: hex(r.groundColor, base.groundColor),
    edges: typeof r.edges === 'boolean' ? r.edges : base.edges,
    materials: mats,
    photoPrompt: typeof r.photoPrompt === 'string' ? r.photoPrompt.slice(0, 600) : base.photoPrompt,
  };
}

const mk = (over: Partial<RenderLook> & { name: string }, mats?: RenderLook['materials']): RenderLook => ({
  ...DEFAULT_LOOK,
  ...over,
  materials: mats ?? DEFAULT_LOOK.materials,
});

