export const LOOK_INSTRUCTIONS = `You are an architectural visualization artist. You set up the lighting, sky and materials of a real-time 3D architectural model so that a render matches the client's brief.
You may be shown a screenshot of the current 3D view: use it to understand the building (style, size, roof, glazing) and keep the result believable for it.
Colours are hex #rrggbb in sRGB. Pick realistic material colours (real stone, render, brick, timber, metal, glass-frame colours), not saturated primaries, unless the brief asks for a diagrammatic look.
Sun: altitude in degrees above the horizon; azimuth is the compass bearing the sun shines FROM (0 = north/top of the plan, 90 = east, 180 = south, 270 = west). Golden hour ≈ 5–12°, midday ≈ 50–70°, dusk ≈ 0–3° with low intensity and stronger ambient.
Exposure 1 is neutral; raise it a little for dusk and night. Fog is haze: 0.05–0.2 for clear air, 0.3+ for misty or dusk scenes.
Interior lights at night: give window frames a warm glowing colour (e.g. #f2c26b) only for night or dusk briefs.
photoPrompt is passed to a photoreal image model: describe materials, landscaping, people/cars only if asked, weather and mood in one or two sentences.`;

/** Plain-language summary for the command line. */
export function describeLook(l: RenderLook): string {
  const sun = l.sunAltitude < 3 ? 'sun on the horizon' : `sun ${Math.round(l.sunAltitude)}° high from ${compass(l.sunAzimuth)}`;
  return `${l.name}: ${sun}, exposure ${l.exposure.toFixed(2)}${l.fogDensity > 0.25 ? ', hazy' : ''}${l.edges ? ', outlined' : ''}.`;
}

export function compass(az: number): string {
  const names = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
  return names[Math.round((((az % 360) + 360) % 360) / 45) % 8];
}

/**
 * Sun direction (unit vector, three.js world: x = plan x, y = up, z = plan y which points SOUTH
 * because the plan is y-down) for a compass azimuth + altitude.
 */
export function sunDirection(azimuthDeg: number, altitudeDeg: number): { x: number; y: number; z: number } {
  const az = (azimuthDeg * Math.PI) / 180;
  const alt = (Math.max(0.5, altitudeDeg) * Math.PI) / 180;
  const h = Math.cos(alt);
  // north = −z (plan top), east = +x
  return { x: Math.sin(az) * h, y: Math.sin(alt), z: -Math.cos(az) * h };
}

const LS_KEY = 'archiforma_render_looks_v1';
export function loadSavedLooks(): RenderLook[] {
  try {
    const raw = JSON.parse(localStorage.getItem(LS_KEY) || '[]');
    return Array.isArray(raw) ? raw.slice(0, 24).map((r) => normalizeLook(r)) : [];
  } catch {
    return [];
  }
}
export function saveLooks(looks: RenderLook[]) {
  try {
    localStorage.setItem(LS_KEY, JSON.stringify(looks.slice(0, 24)));
  } catch {
    /* storage unavailable */
  }
}
